 17	package org.springframework.samples.petclinic;
 18	
 19	import static org.assertj.core.api.Assertions.assertThat;
 20	import static org.assertj.core.api.Assertions.assertThatThrownBy;
 21	
 22	import java.sql.Date;
 23	
 24	import javax.sql.DataSource;
 25	
 26	import org.springframework.core.io.ClassPathResource;
 27	import org.springframework.dao.DataIntegrityViolationException;
 28	import org.springframework.jdbc.core.JdbcTemplate;
 29	import org.springframework.jdbc.datasource.init.ResourceDatabasePopulator;
 30	
 31	/**
 32	 * The PC-301 deployment steps, run against an empty MySQL or Postgres database: release
 33	 * 1's schema and seed data, then the migration script, then release 1 again (what a
 34	 * rollback redeploys), then release 2's schema and seed data. Release 1's scripts are
 35	 * kept as test resources under {@code pc-301-release-1/}.
 36	 */
 37	class MicrochipNumberMigrationScenario {
 38	
 39		private static final String NUMBER = "985141000123456";
 40	
 41		private final DataSource dataSource;
 42	
 43		private final JdbcTemplate jdbc;
 44	
 45		private final String database;
 46	
 47		private final String currentSchema;
 48	
 49		/**
 50		 * @param database {@code mysql} or {@code postgres}
 51		 * @param currentSchema the SQL expression for the schema the tables are in
 52		 */
 53		MicrochipNumberMigrationScenario(DataSource dataSource, String database, String currentSchema) {
 54			this.dataSource = dataSource;
 55			this.jdbc = new JdbcTemplate(dataSource);
 56			this.database = database;
 57			this.currentSchema = currentSchema;
 58		}
 59	
 60		void run() {
 61			// Release 1 on an empty database: the pets table before this change.
 62			runReleaseOne();
 63			assertThat(hasMicrochipNumberColumn()).as("pets has no microchip_number column before the migration").isFalse();
 64			this.jdbc.update("INSERT INTO pets (name, birth_date, type_id, owner_id) VALUES (?, ?, ?, ?)", "Unchipped",
 65					Date.valueOf("2020-01-01"), 1, 1);
 66			Integer existingPetId = this.jdbc.queryForObject("SELECT id FROM pets WHERE owner_id = 1 AND name = ?",
 67					Integer.class, "Unchipped");
 68	
 69			runScript("db/" + this.database + "/migrate-pc-301-microchip-number.sql");
 70	
 71			assertThat(hasMicrochipNumberColumn()).isTrue();
 72			assertThat(
 73					this.jdbc.queryForObject("SELECT microchip_number FROM pets WHERE id = ?", String.class, existingPetId))
 74				.isNull();
 75			assertThat(
 76					this.jdbc.queryForObject("SELECT COUNT(*) FROM pets WHERE microchip_number IS NOT NULL", Integer.class))
 77				.isZero();
 78	
 79			insertPet("NoChipOne", 1, null);
 80			insertPet("NoChipTwo", 2, null);
 81	
 82			insertPet("ChipOne", 1, NUMBER);
 83			assertThatThrownBy(() -> insertPet("ChipTwo", 2, NUMBER)).isInstanceOf(DataIntegrityViolationException.class)
 84				.satisfies(ex -> assertThat(ex.getMessage()).containsIgnoringCase("unique_pet_microchip_number"));
 85	
 86			// Rollback from release 2 redeploys release 1: it must start on the migrated
 87			// table.
 88			runReleaseOne();
 89	
 90			// Deployment step 3: release 2 starts on the migrated table.
 91			runScript("db/" + this.database + "/schema.sql");
 92			runScript("db/" + this.database + "/data.sql");
 93			assertThat(
 94					this.jdbc.queryForObject("SELECT COUNT(*) FROM pets WHERE microchip_number = ?", Integer.class, NUMBER))
 95				.isEqualTo(1);
 96		}
 97	
 98		private void runReleaseOne() {
 99			runScript("pc-301-release-1/" + this.database + "/schema.sql");
100			runScript("pc-301-release-1/" + this.database + "/data.sql");
101		}
102	
103		private void runScript(String path) {
104			new ResourceDatabasePopulator(new ClassPathResource(path)).execute(this.dataSource);
105		}
106	
107		private boolean hasMicrochipNumberColumn() {
108			Integer count = this.jdbc.queryForObject("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = "
109					+ this.currentSchema + " AND table_name = 'pets' AND column_name = 'microchip_number'", Integer.class);
110			return count != null && count > 0;
111		}
112	
113		private void insertPet(String name, int ownerId, String microchipNumber) {
114			this.jdbc.update(
115					"INSERT INTO pets (name, birth_date, type_id, owner_id, microchip_number) VALUES (?, ?, ?, ?, ?)", name,
116					Date.valueOf("2020-01-01"), 1, ownerId, microchipNumber);
117		}
118	
119	}
