 46	@Controller
 47	@RequestMapping("/owners/{ownerId}")
 48	class PetController {
 49	
 50		private static final String VIEWS_PETS_CREATE_OR_UPDATE_FORM = "pets/createOrUpdatePetForm";
 51	
 52		private final OwnerRepository owners;
 53	
 54		private final PetTypeRepository types;
 55	
 56		private final PetValidator petValidator;
 57	
 58		public PetController(OwnerRepository owners, PetTypeRepository types, PetRepository pets) {
 59			this.owners = owners;
 60			this.types = types;
 61			this.petValidator = new PetValidator(pets);
 62		}
 63	
 64		@ModelAttribute("types")
 65		public Collection<PetType> populatePetTypes() {
 66			return this.types.findPetTypes();
 67		}
 68	
 69		@ModelAttribute("owner")
 70		public Owner findOwner(@PathVariable("ownerId") int ownerId) {
 71			Optional<Owner> optionalOwner = this.owners.findById(ownerId);
 72			Owner owner = optionalOwner.orElseThrow(() -> new IllegalArgumentException(
 73					"Owner not found with id: " + ownerId + ". Please ensure the ID is correct "));
 74			return owner;
 75		}
 76	
 77		@ModelAttribute("pet")
 78		public Pet findPet(@PathVariable("ownerId") int ownerId,
 79				@PathVariable(name = "petId", required = false) Integer petId) {
 80	
 81			if (petId == null) {
 82				return new Pet();
 83			}
 84	
 85			Optional<Owner> optionalOwner = this.owners.findById(ownerId);
 86			Owner owner = optionalOwner.orElseThrow(() -> new IllegalArgumentException(
 87					"Owner not found with id: " + ownerId + ". Please ensure the ID is correct "));
 88			return owner.getPet(petId);
 89		}
 90	
 91		@InitBinder("owner")
 92		public void initOwnerBinder(WebDataBinder dataBinder) {
 93			dataBinder.setDisallowedFields("id", "*.id");
 94		}
 95	
 96		@InitBinder("pet")
 97		public void initPetBinder(WebDataBinder dataBinder) {
 98			dataBinder.setValidator(this.petValidator);
 99			dataBinder.setDisallowedFields("id", "*.id");
100		}
101	
102		@GetMapping("/pets/new")
103		public String initCreationForm(Owner owner, ModelMap model) {
104			Pet pet = new Pet();
105			owner.addPet(pet);
106			return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
107		}
108	
109		@PostMapping("/pets/new")
110		public String processCreationForm(Owner owner, @Valid Pet pet, BindingResult result,
111				RedirectAttributes redirectAttributes) {
112	
113			if (StringUtils.hasText(pet.getName()) && pet.isNew() && owner.getPet(pet.getName(), true) != null) {
114				result.rejectValue("name", "duplicate", "already exists");
115			}
116	
117			if (result.hasErrors()) {
118				return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
119			}
120	
121			try {
122				owner.addPet(pet);
123				this.owners.saveAndFlush(owner);
124			}
125			catch (DataIntegrityViolationException ex) {
126				if (isDuplicateMicrochipNumberViolation(ex)) {
127					this.petValidator.rejectDuplicateMicrochipNumber(result);
128					return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
129				}
130				if (!isDuplicatePetNameViolation(ex)) {
131					throw ex;
132				}
133				result.rejectValue("name", "duplicate", "already exists");
134				return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
135			}
136			redirectAttributes.addFlashAttribute("message", "New Pet has been Added");
137			return "redirect:/owners/{ownerId}";
138		}
139	
140		@GetMapping("/pets/{petId}/edit")
141		public String initUpdateForm() {
142			return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
143		}
144	
145		@PostMapping("/pets/{petId}/edit")
146		public String processUpdateForm(Owner owner, @Valid Pet pet, BindingResult result,
147				RedirectAttributes redirectAttributes) {
148	
149			if (isNameTakenByAnotherPet(owner, pet)) {
150				result.rejectValue("name", "duplicate", "already exists");
151			}
152	
153			if (result.hasErrors()) {
154				return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
155			}
156	
157			try {
158				updatePetDetails(owner, pet);
159			}
160			catch (DataIntegrityViolationException ex) {
161				if (isDuplicateMicrochipNumberViolation(ex)) {
162					this.petValidator.rejectDuplicateMicrochipNumber(result);
163					return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
164				}
165				if (!isDuplicatePetNameViolation(ex)) {
166					throw ex;
167				}
168				result.rejectValue("name", "duplicate", "already exists");
169				return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
170			}
171			redirectAttributes.addFlashAttribute("message", "Pet details has been edited");
172			return "redirect:/owners/{ownerId}";
173		}
174	
175		private boolean isNameTakenByAnotherPet(Owner owner, Pet pet) {
176			if (!StringUtils.hasText(pet.getName())) {
177				return false;
178			}
179			Pet existingPet = owner.getPet(pet.getName(), false);
180			return existingPet != null && !Objects.equals(existingPet.getId(), pet.getId());
181		}
182	
183		/**
184		 * Updates the pet details if it exists or adds a new pet to the owner.
185		 * @param owner The owner of the pet
186		 * @param pet The pet with updated details
187		 */
188		private void updatePetDetails(Owner owner, Pet pet) {
189			Integer id = pet.getId();
190			Assert.state(id != null, "'pet.getId()' must not be null");
191			Pet existingPet = owner.getPet(id);
192			if (existingPet != null) {
193				// Update existing pet's properties
194				existingPet.setName(pet.getName());
195				existingPet.setBirthDate(pet.getBirthDate());
196				existingPet.setType(pet.getType());
197				// null included: an empty field removes the stored number
198				existingPet.setMicrochipNumber(pet.getMicrochipNumber());
199			}
200			else {
201				owner.addPet(pet);
202			}
203			this.owners.saveAndFlush(owner);
204		}
205	
206		private boolean isDuplicatePetNameViolation(DataIntegrityViolationException ex) {
207			String message = ex.getMessage();
208			return message != null && message.toLowerCase().contains("unique_owner_pet_name");
209		}
210	
211		private boolean isDuplicateMicrochipNumberViolation(DataIntegrityViolationException ex) {
212			String message = ex.getMessage();
213			return message != null && message.toLowerCase().contains("unique_pet_microchip_number");
214		}
215	
216	}
