 17	
 18	import java.time.LocalDate;
 19	import java.util.regex.Pattern;
 20	
 21	import org.springframework.util.StringUtils;
 22	import org.springframework.validation.Errors;
 23	import org.springframework.validation.Validator;
 24	
 25	/**
 26	 * <code>Validator</code> for <code>Pet</code> forms.
 27	 * <p>
 28	 * We're not using Bean Validation annotations here because it is easier to define such
 29	 * validation rule in Java.
 30	 * </p>
 31	 *
 32	 * @author Ken Krebs
 33	 * @author Juergen Hoeller
 34	 */
 35	public class PetValidator implements Validator {
 36	
 37		private static final String REQUIRED = "required";
 38	
 39		private static final int MAX_NAME_LENGTH = 30;
 40	
 41		private static final String MICROCHIP_NUMBER = "microchipNumber";
 42	
 43		// [0-9] rather than \d, so the rule cannot widen to other digit characters.
 44		private static final Pattern MICROCHIP_NUMBER_FORMAT = Pattern.compile("[0-9]{15}");
 45	
 46		private final PetRepository pets;
 47	
 48		public PetValidator(PetRepository pets) {
 49			this.pets = pets;
 50		}
 51	
 52		@Override
 53		public void validate(Object obj, Errors errors) {
 54			Pet pet = (Pet) obj;
 55			String name = pet.getName();
 56			// name validation
 57			if (!StringUtils.hasText(name)) {
 58				errors.rejectValue("name", REQUIRED, REQUIRED);
 59			}
 60			else if (name.length() > MAX_NAME_LENGTH) {
 61				errors.rejectValue("name", "size", "Name must be no more than 30 characters");
 62			}
 63	
 64			// type validation
 65			if (pet.isNew() && pet.getType() == null) {
 66				errors.rejectValue("type", REQUIRED, REQUIRED);
 67			}
 68	
 69			// birth date validation
 70			if (pet.getBirthDate() == null) {
 71				errors.rejectValue("birthDate", REQUIRED, REQUIRED);
 72			}
 73			else if (pet.getBirthDate().isAfter(LocalDate.now())) {
 74				errors.rejectValue("birthDate", "typeMismatch.birthDate");
 75			}
 76	
 77			// microchip number validation: optional, and at most one error. The uniqueness
 78			// query runs only for a well-formed number, never for a pet without one.
 79			String microchipNumber = pet.getMicrochipNumber();
 80			if (microchipNumber != null) {
 81				if (!MICROCHIP_NUMBER_FORMAT.matcher(microchipNumber).matches()) {
 82					errors.rejectValue(MICROCHIP_NUMBER, "microchipNumber.invalid");
 83				}
 84				else if (isMicrochipNumberTakenByAnotherPet(pet)) {
 85					rejectDuplicateMicrochipNumber(errors);
 86				}
 87			}
 88		}
 89	
 90		/**
 91		 * Rejects the microchip number as a duplicate. The controller calls this when the
 92		 * database's unique constraint catches a duplicate that validation could not see. The
 93		 * error names no other pet or owner.
 94		 */
 95		public void rejectDuplicateMicrochipNumber(Errors errors) {
 96			errors.rejectValue(MICROCHIP_NUMBER, "duplicate");
 97		}
 98	
 99		private boolean isMicrochipNumberTakenByAnotherPet(Pet pet) {
100			// A new pet has no id, and "id <> NULL" never matches, so it needs its own query.
101			if (pet.isNew()) {
102				return this.pets.existsByMicrochipNumber(pet.getMicrochipNumber());
103			}
104			return this.pets.existsByMicrochipNumberAndIdNot(pet.getMicrochipNumber(), pet.getId());
105		}
106	
107		/**
108		 * This Validator validates *just* Pet instances
109		 */
110		@Override
111		public boolean supports(Class<?> clazz) {
112			return Pet.class.isAssignableFrom(clazz);
113		}
114	
115	}
