 82						ResponseEntity<String> response = template.postForEntity("/owners/" + ownerId + "/pets/new",
 83								request, String.class);
 84	
 85						String body = response.getBody();
 86						// If the response page contains the duplicate validation error, it
 87						// was blocked
 88						if (response.getStatusCode().is2xxSuccessful()
