107				assertThat(ready).isTrue();
108				startLatch.countDown();
109				boolean completed = doneLatch.await(10, TimeUnit.SECONDS);
110				assertThat(completed).isTrue();
111			}
112			finally {
113				executorService.shutdown();
114			}
