120			System.out.println("Successful additions: " + successCount.get());
121			System.out.println("Failed additions: " + failureCount.get());
122			System.out.println("Original Pet Count: " + initialPetCount);
123			System.out.println("Final Pet Count: " + newPetCount);
124	
125			// With the fix, exactly ONE concurrent request must succeed
126			assertThat(successCount.get()).isEqualTo(1);
127			assertThat(newPetCount).isEqualTo(initialPetCount + 1);
